        using(var modules=new ModulesView(prefs,true)){var draft=new Preferences();modules.Apply(draft,false);c["settings_preserve_new_module_switches"]=draft.DesktopMailModule&&!draft.SystemMonitorModule;}
        bool show=true;using(var monitor=new ComputerMonitor(new Sampler(),()=>true,()=>false,()=>show,_=>{})){using var form=new ComputerStatusForm(monitor,prefs,change=>change(prefs),_=>Task.CompletedTask);form.StartPosition=FormStartPosition.Manual;form.Location=new(-19000,-19000);form.Show();monitor.Configure();await monitor.Tick();c["monitor_ui_shows_fake_values_and_process"]=Walk(form).OfType<ListView>().Single().Items[0].Text=="fixture-process"&&Walk(form).OfType<Label>().Any(l=>l.Text.Contains("25.0%"));var list=Walk(form).OfType<ListView>().Single();typeof(ListView).GetMethod("OnColumnClick",System.Reflection.BindingFlags.Instance|System.Reflection.BindingFlags.NonPublic)!.Invoke(list,[new ColumnClickEventArgs(3)]);c["memory_column_sorts_actual_rows"]=list.Items[0].Text=="fixture-memory";typeof(ListView).GetMethod("OnColumnClick",System.Reflection.BindingFlags.Instance|System.Reflection.BindingFlags.NonPublic)!.Invoke(list,[new ColumnClickEventArgs(2)]);c["cpu_column_restores_cpu_order"]=list.Items[0].Text=="fixture-process";using var png=new Bitmap(form.Width,form.Height);form.DrawToBitmap(png,new Rectangle(Point.Empty,form.Size));png.Save(Path.Combine(folder,"computer-status.png"));form.Close();show=false;monitor.Configure();c["window_close_unsubscribes_and_stops"]=!monitor.Active;}
        using(var form=new MailClientForm(prefs,change=>change(prefs),()=>Task.CompletedTask,true)){form.StartPosition=FormStartPosition.Manual;form.Location=new(-19000,-19000);form.Show();c["mail_ui_has_no_credential_fields"]=Walk(form).OfType<TextBox>().Count()==1&&Walk(form).OfType<Label>().Any(l=>l.Text.Contains("不读取邮件"));using var png=new Bitmap(form.Width,form.Height);form.DrawToBitmap(png,new Rectangle(Point.Empty,form.Size));png.Save(Path.Combine(folder,"mail-client.png"));form.Close();}
        // Regression: the real cache can exceed the action boundary; do not forward unrelated games.
        var match=new FootballMatch("123456",DateTimeOffset.Now.AddDays(2),"fixture","83","Barcelona","86","Real Madrid","pre","Scheduled","VS",true);
        var large=Enumerable.Range(0,2200).Select(i=>match with{Id=(100000+i).ToString()}).Append(match).ToArray();
        string todoRoot=Path.Combine(folder,"hydrate-"+Guid.NewGuid().ToString("N"));Directory.CreateDirectory(todoRoot);var todos=new TodoStore(Path.Combine(todoRoot,"tasks.json"));using var todoBus=new ActionDispatcher(new(),(_,_,_)=>throw new Exception("no legacy"),new ExtensionStore(Path.Combine(folder,"no-extensions")));todoBus.Registry.Register(new TodoCapability(todos,(work,t)=>{t.ThrowIfCancellationRequested();work();return Task.CompletedTask;},_=>{},_=>null));var client=new TodoClient(todos,todoBus,"football-sync");
        c["large_cache_reproduces_previous_oversize"]=JsonSerializer.Serialize(new{matches=large,observed=t}).Length>125000;
        client.HydrateMatchMetadata(large,t);c["large_cache_without_match_tasks_needs_no_action"]=!todoBus.RecentResults.Any();
        var legacy=client.Add("fixture match",DateOnly.FromDateTime(match.Kickoff.LocalDateTime),match.Kickoff.AddMinutes(-10));client.Delete(legacy.Id);client.Restore(legacy with{MatchId="espn:"+match.Id,MatchKickoff=null});client.HydrateMatchMetadata(large,t);
        c["large_cache_hydrates_only_relevant_task"]=client.Items.Single().MatchKickoff==match.Kickoff&&client.Items.Single().MatchFollowSchedule;
        c["hydrated_tasks_no_longer_forward_entire_cache"]=!MatchSyncService.TrackedIds(todos).Except([match.Id]).Any();
        foreach(var entry in BuiltinIcons.Entries){using var icon=BuiltinIcons.TryCreate("glyph:"+entry.Id);c["icon_"+entry.Id]=icon?.Width==48;}c["invalid_builtin_icon_rejected"]=LocalApplications.Icon("glyph:unknown")==null;
        using(var picker=new BuiltinIconPicker()){picker.Show();c["builtin_icon_picker_has_all_choices"]=Walk(picker).OfType<GlyphButton>().Count()==BuiltinIcons.Entries.Length;using var png=new Bitmap(picker.Width,picker.Height);picker.DrawToBitmap(png,new(Point.Empty,picker.Size));png.Save(Path.Combine(folder,"icon-library.png"));picker.Close();}
        using(var chatHost=new Form{ClientSize=new(560,450)}){using var view=new ConversationView{Dock=DockStyle.Fill};chatHost.Controls.Add(view);chatHost.Show();
            var turns=new[]{new ChatTurn{User="测试多行排版",Assistant=string.Concat(Enumerable.Repeat("中文换行与 English wrapping 123456789。\n",18))+"末行完整显示",Status="完成"}};
            bool fits=true;foreach(int width in new[]{560,490,900,510}){chatHost.ClientSize=new(width,450);view.Display(turns);Application.DoEvents();foreach(var text in Walk(view).OfType<RichTextBox>()){text.SelectionStart=0;text.ScrollToCaret();fits&=text.GetPositionFromCharIndex(text.TextLength).Y+text.Font.Height<text.ClientSize.Height||text.ScrollBars==RichTextBoxScrollBars.Vertical;}}
            c["chat_native_wrapping_fits_after_repeated_resize"]=fits;c["chat_resize_has_no_horizontal_overflow"]=!view.HorizontalScroll.Visible;File.WriteAllText(Path.Combine(folder,"chat-layout.json"),JsonSerializer.Serialize(new{client=view.ClientSize,display=view.DisplayRectangle,scroll=view.AutoScrollPosition,rows=view.Controls.Cast<Control>().Select(x=>new{x.Bounds,children=x.Controls.Cast<Control>().Select(y=>y.Bounds)})}));using var png=new Bitmap(chatHost.Width,chatHost.Height);chatHost.DrawToBitmap(png,new(Point.Empty,chatHost.Size));png.Save(Path.Combine(folder,"chat-wrapping.png"));chatHost.Close();}
