sealed partial class ChatForm
{
    internal bool VerifyLocalResultLayout(){ClearResults();ResultText(string.Concat(Enumerable.Repeat("清单执行反馈很长时也需要完整显示，并随窗口宽度重新换行。\n",30)));ClientSize=new(500,520);Application.DoEvents();var label=results.Controls.OfType<Label>().Single();int narrow=label.Height;ClientSize=new(920,600);Application.DoEvents();return narrow>400&&label.Height<=narrow&&label.Height>=label.GetPreferredSize(new(label.Width,0)).Height;}
